import os
from setuptools import setup, Extension
from setuptools.command.build_ext import build_ext as _build_ext
TARGET_INCLUDE={p1}
TARGET_LIBDIR={p3}
TARGET_LIBRARIES={p5}
TARGET_SUFFIX={p7}
EXTENSIONS={p9}
class TargetBuildExt(_build_ext):
    def finalize_options(self):
        super().finalize_options()
        self.include_dirs=[TARGET_INCLUDE]
        self.library_dirs=[TARGET_LIBDIR]
    def get_ext_fullpath(self, ext_name):
        fullname = self.get_ext_fullname(ext_name)
        return os.path.join(self.build_lib, *fullname.split('.')) + TARGET_SUFFIX
    def get_export_symbols(self, ext):
        # A bundle has no PyInit_<bundle> entry point: every translation
        # unit was renamed individually and register.c exports the single
        # symbol the launcher resolves. MSVC would otherwise add
        # /EXPORT:PyInit_<bundle> and fail with LNK2001.
        return ['ai_upper_register_modules']
extensions=[Extension(n,s,include_dirs=[TARGET_INCLUDE],library_dirs=[TARGET_LIBDIR],libraries=TARGET_LIBRARIES) for n,s in EXTENSIONS]
setup(name='ai-upper-target-merged',ext_modules=extensions,cmdclass={'build_ext':TargetBuildExt})

